import pandas as pd
import numpy as np
import pickle

# Load data and charts
df = pd.read_csv('benchmark/data.csv')
df['has_wicket'] = df['wicket_type'].notna() & (df['wicket_type'] != '')
df['over_num'] = df['over'].astype(int)
df['total_runs'] = df['runs_of_bat'] + df['extras']
df['is_boundary'] = (df['runs_of_bat'] == 4) | (df['runs_of_bat'] == 6)
df['is_dot'] = (df['runs_of_bat'] == 0) & (df['extras'] == 0)
df['phase'] = df['over_num'].apply(lambda x: 'Powerplay' if x < 6 else ('Middle' if x < 15 else 'Death'))

with open('/app/output/charts.pkl', 'rb') as f:
    charts = pickle.load(f)

# Compute all metrics
num_matches = df['match_no'].nunique()
num_venues = df['venue'].nunique()
teams = sorted(df['batting_team'].unique().tolist())
total_deliveries = len(df)
total_runs = df['total_runs'].sum()
total_wickets = df['has_wicket'].sum()
total_extras = df['extras'].sum()
overs_count = df.groupby(['match_no', 'innings'])['over_num'].nunique().reset_index()
total_overs = overs_count['over_num'].sum()

kpi_values = {
    'avg_runs_per_over': total_runs / total_overs,
    'boundary_pct': df['is_boundary'].mean() * 100,
    'dot_ball_pct': df['is_dot'].mean() * 100,
    'extras_per_match': total_extras / num_matches,
    'wickets_per_match': total_wickets / num_matches
}

# Batting
batting = df.groupby('striker').agg(
    runs=('runs_of_bat', 'sum'),
    balls=('runs_of_bat', 'count'),
    fours=('runs_of_bat', lambda x: (x == 4).sum()),
    sixes=('runs_of_bat', lambda x: (x == 6).sum())
).reset_index()
batting['strike_rate'] = batting['runs'] / batting['balls'] * 100
batting['boundary_pct'] = (batting['fours'] + batting['sixes']) / batting['balls'] * 100
top_batsmen = batting.sort_values('runs', ascending=False).head(10)

phase_batting = df.groupby('phase').agg(
    runs=('total_runs', 'sum'),
    balls=('runs_of_bat', 'count'),
    boundaries=('is_boundary', 'sum'),
    wickets=('has_wicket', 'sum')
).reset_index()
phase_batting['strike_rate'] = phase_batting['runs'] / phase_batting['balls'] * 100

# Bowling
bowling = df.groupby('bowler').agg(
    balls=('runs_of_bat', 'count'),
    runs_conceded=('total_runs', 'sum'),
    wickets=('has_wicket', 'sum'),
    dots=('is_dot', 'sum')
).reset_index()
bowling['overs'] = bowling['balls'] / 6
bowling['economy'] = bowling['runs_conceded'] / bowling['overs']
bowling['dot_pct'] = bowling['dots'] / bowling['balls'] * 100
bowling['strike_rate'] = bowling['balls'] / bowling['wickets'].replace(0, np.nan)
bowling_min = bowling[bowling['balls'] >= 12]

top_wickets = bowling_min[bowling_min['wickets'] > 0].sort_values('wickets', ascending=False).head(10)
